import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/Wiki%E3%81%A8%E6%89%8B%E6%9B%B8%E3%81%8D%E3%83%8E%E3%83%BC%E3%83%88%E3%81%AE%E8%9E%8D%E5%90%88.html","title":"Wikiと手書きノートの融合","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":2.66,"words":798},"filePathRelative":"Wikiと手書きノートの融合.md"}`),a={name:`Wikiと手書きノートの融合.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="wikiと手書きノートの融合" tabindex="-1"><a class="header-anchor" href="#wikiと手書きノートの融合"><span>Wikiと手書きノートの融合</span></a></h1><p><a href="./ノート.html">ノート</a>より。</p><p><a href="./講義ノート.html">講義ノート</a>と同じような話だが、<a href="./TeFWiki.html">TeFWiki</a>と<a href="./PngNote.html">PngNote</a>の融合について、 特にPngNoteの方がメインのノートを作った時に、これをどうWikiと融合させるかについて考えたい。</p><h2 id="問題設定" tabindex="-1"><a class="header-anchor" href="#問題設定"><span>問題設定</span></a></h2><p>テキストにちょっと補助で画像を描く、という場合は、適当に作った画像をFireAlpacaで範囲指定コピーして、 それを<a href="./MdImgr.html">MdImgr</a>に貼る、で良いように思う。 Wikiに直接貼るのにくらべてちょっとだけ手間もあるが、 コピー先のフォルダのコントロールが出来る分この手間は妥当だと思っている。 <a href="./【書籍】イラストをそれっぽく描くコツ.html">【書籍】イラストをそれっぽく描くコツ</a>などはいい感じに出来たページだと思っている。</p><p>数式などをちょっと手書きで足したい、という時も、同様のスタイルで良い。</p><p>だが、テキストと手書きを行ったり来たりが増えてくるとこのスタイルはかったるく、 手書きをメインにノートを書く事はちょくちょくある。図書館などではタイピングの音がうるさいのは良くない、という事情もあり、<a href="./PngNote.html">PngNote</a>だけでノートをとる方が手軽な事も多い。</p><p>この手書きで書いたノートをそのまま放置していると、後で見直せない。 そこでどうにか省エネでWikiに統合したい。ただ取り込むのを面倒にするとやらないので、取り込みの省エネ具合を優先し、見る側の多少のいまいちは受け入れる事にする。</p><h2 id="前提" tabindex="-1"><a class="header-anchor" href="#前提"><span>前提</span></a></h2><ul><li>手書きのノートはそこまで形態を変えたくない <ul><li>たまに改ページするくらいはいい</li><li>コピペしたい単位ごとに改ページは嫌だ</li></ul></li><li>取り込みは最小の手間でやりたい <ul><li>気が向くまでそれを整理していく、という風にプラスアルファで整理したければする形にしたい</li></ul></li><li>気が向いたら<a href="./PngNote.html">PngNote</a>に戻して続きを書いたりはしたい</li></ul><h2 id="ソリューション" tabindex="-1"><a class="header-anchor" href="#ソリューション"><span>ソリューション</span></a></h2><ul><li>PngNoteのフォルダをそのままimgs下に移動する</li><li>trim_and_kick.appにimgs下に移動したフォルダをDnD</li><li>立ち上がった<a href="./MdImgr.html">MdImgr</a>のCopyAllUrlsで全リンクをコピーしてmdにペースト</li><li>md上で適当にセクションとかに分けて、たまに説明を足したりする</li></ul><p>これはかなりいい感じになっている。</p><h3 id="trim-and-kick-app" tabindex="-1"><a class="header-anchor" href="#trim-and-kick-app"><span>trim_and_kick.app</span></a></h3><p>上記の手順のtrim_and_kick.appはApple Scriptで作ったのだが、後から見るとなんだったか忘れがちなのでここにメモを残す。</p><p>やっている事は以下</p><ul><li>フォルダをバックアップを取りつつ余白除去をするスクリプトを走らせる(<a href="./Go.html">Go</a>で書いた。<a href="https://github.com/karino2/RandomThoughts/tree/master/wiki_src/imgs/scripts" target="_blank" rel="noopener noreferrer">RandomThoughts/wiki_src/imgs/scripts</a>）</li><li><a href="./MdImgr.html">MdImgr</a>を立ち上げる</li></ul><p>何をやってるか忘れた時は、trim_and_kick.app/Contents/Resources/trim_bottom_kick.commandを見ると何をやるかはだいたい分かる。 このtrim_and_kick.app自体はスクリプトエディタというアプリで開ける。</p><h2 id="このソリューションの実例" tabindex="-1"><a class="header-anchor" href="#このソリューションの実例"><span>このソリューションの実例</span></a></h2><ul><li><a href="./HMM.html">HMM</a></li><li><a href="./マルコフ連鎖.html">マルコフ連鎖</a></li><li><a href="./文字列マッチ.html">文字列マッチ</a></li><li><a href="./EnhancedSuffixArray.html">EnhancedSuffixArray</a></li></ul><h2 id="感想" tabindex="-1"><a class="header-anchor" href="#感想"><span>感想</span></a></h2><p><a href="./EnhancedSuffixArray.html">EnhancedSuffixArray</a>は割と手を入れたものになっていて、逆に<a href="./HMM.html">HMM</a>などは全く手が入ってない例となる。</p><p>取り込むコストはかなり低い。1ページずつコピペせずにbook単位で取り込めるがの良い。 PngNoteで書いたノートをアーカイブする感覚で出来る。</p><p>そして省エネでありながら、Wikiのリンク先が出来る、というのは結構大きい。 リンクのネットワークがより充実していくのが分かるし、後から見直しやすい。 手書きのノートを単に<a href="./GithubPagesGallery.html">GithubPagesGallery</a>に置くだけではほとんど見直さないが、 Wikiに埋め込む所までやればちゃんと見直せるノートにはなっている。</p><p><a href="./マルコフ連鎖.html">マルコフ連鎖</a>などでは、複数の教科書を読みながら書いたが、 教科書の区切りでは改ページをしておいたので、Wiki上ではセクションは区切れる。このくらいはやっても良い気がしている。</p><p>本当はStationaryとか単位でcropしたいのだが、この手間を掛ける気は今の所起こらないなぁ。 Wikiからちょろっと出来るならやりたい所だが、わざわざお絵描きアプリを立ち上げてそうした作業をする気は起こらない。 コマンドラインからキック出来る専用アプリがあればやるかもしれないが、 それをやるとPngNoteに戻すのが面倒になるので一長一短ではある。</p><p>一度取り込んだノートをもう一度<a href="./PngNote.html">PngNote</a>で編集するのはややかったるいが、 ある程度時間を置いて変更しなかったノートはほとんど変更しないので、思ったほど実害は無い。 たまに必要になる事はあるが、たまに必要になった時くらいはその手間を払うのはいいかな、という気はしている。</p><p>むしろ残す気の無い計算などはページを分けておきさえすれば、コピペしたものを一行削除するだけでページごと消せるので、 残さない計算と残すノートをまぁまぁ省エネで分離出来るので、思ったよりもいい感じだ。 昔コピー用紙などに適当に計算を書いては捨てていたが、あの感覚で計算が出来て、けれど出来た結果をノートに出来る感じになっている。いいね。</p><h2 id="連番に振り直すスクリプト" tabindex="-1"><a class="header-anchor" href="#連番に振り直すスクリプト"><span>連番に振り直すスクリプト</span></a></h2><p>一つのPngNoteのフォルダを複数のWikiNameに分離する時に、複数のフォルダに分割する事がある。 この時にPngNoteで再編集する時の事を考えると連番を振り直す方が望ましいのでGeminiに書いてもらう。</p><p>reorder.shという名前で保存して使っている。</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token shebang important">#!/bin/bash</span></span>
<span class="line"></span>
<span class="line"><span class="token assign-left variable">dir</span><span class="token operator">=</span><span class="token string">&quot;<span class="token variable">$1</span>&quot;</span></span>
<span class="line"><span class="token assign-left variable">tmpdir</span><span class="token operator">=</span><span class="token variable"><span class="token variable">$(</span>mktemp <span class="token parameter variable">-d</span><span class="token variable">)</span></span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 全PNGを一時ディレクトリへ退避</span></span>
<span class="line"><span class="token function">mv</span> <span class="token string">&quot;<span class="token variable">$dir</span>&quot;</span>/*.png <span class="token string">&quot;<span class="token variable">$tmpdir</span>/&quot;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 連番を振り直して戻す</span></span>
<span class="line"><span class="token assign-left variable">i</span><span class="token operator">=</span><span class="token number">0</span></span>
<span class="line"><span class="token keyword">for</span> <span class="token for-or-select variable">file</span> <span class="token keyword">in</span> <span class="token string">&quot;<span class="token variable">$tmpdir</span>&quot;</span>/*.png<span class="token punctuation">;</span> <span class="token keyword">do</span></span>
<span class="line">    <span class="token function">mv</span> <span class="token string">&quot;<span class="token variable">$file</span>&quot;</span> <span class="token string">&quot;<span class="token variable">$dir</span>/<span class="token variable"><span class="token variable">$(</span><span class="token builtin class-name">printf</span> <span class="token string">&quot;%04d.png&quot;</span> <span class="token string">&quot;<span class="token variable">$i</span>&quot;</span><span class="token variable">)</span></span>&quot;</span></span>
<span class="line">    <span class="token variable"><span class="token punctuation">((</span>i<span class="token operator">++</span><span class="token punctuation">))</span></span></span>
<span class="line"><span class="token keyword">done</span></span>
<span class="line"></span>
<span class="line"><span class="token function">rmdir</span> <span class="token string">&quot;<span class="token variable">$tmpdir</span>&quot;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="始める前に考えた事" tabindex="-1"><a class="header-anchor" href="#始める前に考えた事"><span>始める前に考えた事</span></a></h2><p>もともとこのページは、どうにかならないかな〜という考えをなんとなく書いていくページだったのだが、 紆余曲折の結果一つの結論に到達したので上記にまとめている。</p><p>ただその紆余曲折自体は残しておきたいので以下に残しておく。</p><h3 id="最初に考えた事" tabindex="-1"><a class="header-anchor" href="#最初に考えた事"><span>最初に考えた事</span></a></h3><p>お絵かきは、<a href="./MdImgr.html">MdImgr</a>で割と融合出来ている＞<a href="./【書籍】イラストをそれっぽく描くコツ.html">【書籍】イラストをそれっぽく描くコツ</a>など. 計算式も<a href="./MdImgr.html">MdImgr</a>ベースで良いような気がしている。</p><p>だが、<a href="./PngNote.html">PngNote</a>の方が主体になると現状はいいつなぎ方が無い。</p><p>例えば今日（2026-07-03 (金)）、HMMについての計算をしてみた。これは<a href="./PngNote.html">PngNote</a>の一つのフォルダになっているが、 テキストの必要製はあまり感じない。 このPngをどこかにおいて、インラインイメージとして全部Wikiに貼る事は出来る。 ただこれはそこまでいい体験でも無い。</p><p>本当は、<a href="./GithubPagesGallery.html">GithubPagesGallery</a>がWikiの中にある感じになるのが理想に思う。</p><p>GithubPagesGalleryにノートを置いてそこへのリンクを貼る、という形式だと、ローカルで見直せないのがいまいちだな、と思う。 だが<a href="./TeFWiki.html">TeFWiki</a>にそうした機能を追加していくのはどうも気が乗らない。なんか違う、という気がする。</p><p>単に画像の連番を置いたフォルダをどう見るか、という話と、そこへのリンクをRandomThoughtsの中にどう埋め込むべきか、という話に思う。</p><p>現状、PngNoteはあまりブラウズ性能が高く無いので、昔のノートを全部置いておくのは嫌だなぁ、という気分になる。 ただアクティブに編集したいノートはそんなに多く無いので、どこかに移動するのが問題とは思わない。 問題は移動したものを見直す手段が無いという所だよなぁ。</p><p>まぁ試しに全部イラインで置いてみよう。<a href="./HMM.html">HMM</a></p><p>短ければとりあえずはこれでいいか。</p><h3 id="単にpngnoteをフォルダコピーしてリンクを埋める-2026-07-16-木" tabindex="-1"><a class="header-anchor" href="#単にpngnoteをフォルダコピーしてリンクを埋める-2026-07-16-木"><span>単にPngNoteをフォルダコピーしてリンクを埋める 2026-07-16 (木)</span></a></h3><p>またこの話を考えたくなったので追記。</p><p>今日は<a href="./アルゴリズム本.html">アルゴリズム本</a>で文字列マッチのあたりを読んでいた。定義などは手書きで描きたいが、acceptやrejectの定義などはテキストで書きたいなぁ、という思いがある。</p><p>現在のPngNoteの位置に対してテキストを書く、という事が出来れば、あとから融合出来ると思うのだが、現状はいい書き方が無い。</p><p>PngNoteのページ数を書いておく、というのはどうだろう？ページのどこか、というのは後から見るのにそんなに難しさは無い。ちょっとやってみるか？</p><p><a href="./文字列マッチ.html">文字列マッチ</a>でやってみる。</p><p>やってみた。手描きでノートを書いて、後でそれを見つつWikiを書いて、最後にフォルダごとコピーしたあとに<a href="./kickimgr.html">kickimgr</a>使ってリンクにしていく。 最後にかったるさはあるが、まぁ続けられる範囲かなぁ。 手描きと文字が両方入ってるメモツール系よりはだいぶマシな使い心地にはなった気がする。 手描きだけだと後で見直すのが難しいが、<a href="./文字列マッチ.html">文字列マッチ</a>くらいなら見直せる。</p><p>PngNoteのフォルダを移動するだけ、というのも楽でいい。これならまぁやっていけるか。</p><h3 id="pngnoteの下部の余白を除去するスクリプトを走らせる-2026-07-27-月" tabindex="-1"><a class="header-anchor" href="#pngnoteの下部の余白を除去するスクリプトを走らせる-2026-07-27-月"><span>PngNoteの下部の余白を除去するスクリプトを走らせる 2026-07-27 (月)</span></a></h3><p>下の余白が気になるのでこれを除去するスクリプトをLLMに作ってもらう。省エネと見やすさのバランスとしてはこんなもんか？という気がし始めている。</p>`,56)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};